'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),crypto=require('node:crypto'),{JSDOM}=require('jsdom'),path=require('node:path');
const read=name=>fs.readFileSync(path.join(process.env.BANK_SIDE_TEMPLATES,name),'utf8'),hash=value=>crypto.createHash('sha256').update(value).digest('hex');
const PIN='be39224f5f2d47eee8cad80060aeb364e72448b5cd1c11a7f7c8fd8d999e1b93',OTHER='5c361607267287f859150ac4f7716d05b94a6ee5bebc0478d11660e947b6a15e',SIDE='af3e69641213564226f92b44c0192afc1e3bbf3cd30ac4d101885d06f6fefab5';
const baseline=fs.readFileSync(process.env.BANK_SIDE_SOURCE,'utf8'),adapterSource=read('native-bank-side-checker-adapter.js'),adapt=vm.runInNewContext(adapterSource+';adaptNativeBankSideChecker;'),serialized=value=>JSON.stringify(value,null,2)+'\n';
const deferred=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b});return{promise,resolve,reject}};
async function until(fn){for(let i=0;i<50;i++){if(fn())return;await new Promise(resolve=>setTimeout(resolve,0));}assert.fail('bank condition not reached');}
function metadata(){return {schema:'exam-usage-shared-reading-bank.v5',summary:{verified_groups:1},groups:[{group_id:'g',paper_id:'kaoyan:2026-01',status:'verified',question_range:[41,45],questions:[{question_id:'q41',number:41}],bank:[{source_option_id:'A',label:'A',correctness:'correct',matched_question_ids:['q41']}],group_evidence_sha256:'c'.repeat(64)}],sentence_bindings:[{sentence_id:'kaoyan:2026-01:s',group_id:'g',paper_id:'kaoyan:2026-01',source_option_id:'A',english:'English 😀',english_hash:hash('English 😀'),reviewed_content_hash:'b'.repeat(64),binding_sha256:'a'.repeat(64)}]};}
function markup(meta){const b=meta.sentence_bindings[0],q=new URLSearchParams({paper:b.paper_id,'anki-codex-sentence':b.sentence_id,'anki-codex-hash':b.english_hash,'anki-codex-review':b.reviewed_content_hash,'anki-codex-en':JSON.stringify([[0,1]])});return '<article class="example-card"><p class="example-text">'+b.english+'</p><p class="example-translation">原译</p><p class="example-source">原题</p><a class="sentence-jump" href="https://fixture.test/exam-library/practice/full-paper.htm?'+q+'">原文</a></article>';}
function fixture(t,options={}){
 const dom=new JSDOM(options.html||'',{url:'https://fixture.test/book/',runScripts:'outside-only'});t.after(()=>dom.window.close());const w=dom.window,doc=w.document;w.TextEncoder=TextEncoder;w.__ankiSlimManualRefresh=true;const calls={digest:[],match:[],parse:[]},trusted=new Set(options.trusted||[serialized(metadata())]);
 Object.defineProperty(w.crypto,'subtle',{value:{digest:async(algorithm,bytes)=>{assert.equal(algorithm,'SHA-256');const raw=Buffer.from(bytes).toString('utf8');calls.digest.push(raw);const pin=trusted.has(raw)?SIDE:hash(raw),buffer=Buffer.from(pin,'hex');return buffer.buffer.slice(buffer.byteOffset,buffer.byteOffset+buffer.byteLength);}}});
 const matcher=(raw,pin)=>{calls.match.push({raw,pin});if(!options.allowAssets)assert.equal(pin,SIDE);return options.match?options.match(raw,pin):Promise.resolve(pin===SIDE?trusted.has(raw):hash(raw)===pin);};
 const bridge=new Function('knownPinMatches',read('native-slim-load-checker-bridge.js')+';return withSlimLoadChecker;')(options.noHelper?undefined:matcher);
 if(options.conflict)Object.defineProperty(w,'__studySlimLoadCheckerCapture',{value:options.conflict,configurable:true});
 const parse=w.JSON.parse.bind(w.JSON);w.JSON.parse=function(raw,...args){calls.parse.push(raw);return parse(raw,...args)};
 if(!options.deferModule)bridge(w,enabled=>w.eval(enabled?adapt(baseline,options.pin||PIN):baseline));
 return{w,doc,calls,trusted,bridge,api:()=>w.AnkiSharedReadingBankRuntime};
}

test('real Bank SIDE_SHA comparison uses strict known-pin result instead of digest',async t=>{const f=fixture(t),meta=metadata();await f.api().warm(meta,[]);assert.equal(f.calls.digest.length,0,'old Bank sidecar digest must be replaced at this known-pin comparison only');assert.equal(f.calls.match.length,1);assert.equal(f.calls.match[0].raw,serialized(meta));assert.equal(f.calls.match[0].pin,SIDE);});
test('wrong SIDE and truthy nonboolean checker results still reject at original error boundary',async t=>{for(const result of [false,SIDE,1,{}]){const f=fixture(t,{match:()=>Promise.resolve(result)});await assert.rejects(f.api().warm(metadata(),[]),/shared bank sidecar byte SHA mismatch/);assert.equal(f.calls.parse.length,0);}});
test('metadata snapshot remains synchronous and JSON.parse consumes exactly the checked original bytes',async t=>{const hold=deferred(),f=fixture(t,{match:()=>hold.promise}),meta=metadata(),raw=serialized(meta),pending=f.api().warm(meta,[]);assert.equal(f.calls.match.length,1);assert.equal(f.calls.match[0].raw,raw);meta.summary.verified_groups=999;meta.sentence_bindings[0].english='mutated';hold.resolve(true);await pending;assert.deepEqual(f.calls.parse,[raw]);const h=f.api().install(f.doc,meta);await h.ready;assert.equal(h.diagnostics().verified_groups,1);h.dispose();});
test('same metadata shares one in-flight index verification and failures remain cached for that identity',async t=>{const hold=deferred(),f=fixture(t,{match:()=>hold.promise}),meta=metadata(),first=f.api().warm(meta,[]),second=f.api().warm(meta,[]);first.catch(()=>{});second.catch(()=>{});assert.equal(f.calls.match.length,1);hold.resolve(false);await assert.rejects(first,/byte SHA mismatch/);await assert.rejects(second,/byte SHA mismatch/);meta.summary.verified_groups=8;await assert.rejects(f.api().warm(meta,[]),/byte SHA mismatch/);assert.equal(f.calls.match.length,1);});
test('helper rejection is cached exactly like old digest rejection; new metadata identity can retry',async t=>{const failure=new Error('matcher unavailable');let fail=true;const f=fixture(t,{match:raw=>fail?Promise.reject(failure):Promise.resolve(f.trusted.has(raw))}),meta=metadata();await assert.rejects(f.api().warm(meta,[]),e=>e===failure);fail=false;await assert.rejects(f.api().warm(meta,[]),e=>e===failure);await f.api().warm(metadata(),[]);assert.equal(f.calls.match.length,2);});
test('all schema and unique binding validations still run after successful fixed-pin comparison',async t=>{
 const cases=[['invalid shared bank sidecar',m=>m.schema='bad'],['duplicate shared bank sentence identity',m=>m.sentence_bindings.push({...m.sentence_bindings[0]})],['shared bank binding group missing',m=>m.sentence_bindings[0].group_id='absent'],['shared bank option identity ambiguous',m=>m.groups[0].bank.push({...m.groups[0].bank[0]})]];
 for(const [message,mutate]of cases){const meta=metadata();mutate(meta);const f=fixture(t,{trusted:[serialized(meta)]});await assert.rejects(f.api().warm(meta,[]),e=>e.message===message);assert.equal(f.calls.match.length,message==='invalid shared bank sidecar'?0:1);}
});
test('English digest/cache and bound process projection stay unchanged, only SIDE uses matcher',async t=>{const meta=metadata(),f=fixture(t,{html:markup(meta)});await f.api().warm(meta,[meta.sentence_bindings[0].english,meta.sentence_bindings[0].english]);assert.deepEqual(f.calls.digest,[meta.sentence_bindings[0].english]);assert.equal(f.calls.match.length,1);const before=f.doc.body.innerHTML,h=f.api().install(f.doc,meta);assert.equal(f.api().install(f.doc,meta),h);await h.ready;assert.equal(h.stats().projectedNative,1);assert.equal(f.calls.digest.length,1);assert.equal(f.calls.match.length,1);h.dispose();assert.equal(f.doc.body.innerHTML,before);});
test('dispose/new-card during side verification cannot apply old classifications to current DOM',async t=>{const hold=deferred(),meta=metadata(),f=fixture(t,{html:markup(meta),match:()=>hold.promise}),old=f.api().install(f.doc,meta);old.dispose();f.doc.body.innerHTML='<p id="next">new current card</p>';hold.resolve(true);await old.ready;assert.equal(f.doc.body.innerHTML,'<p id="next">new current card</p>');assert.equal(f.calls.digest.length,0);});
test('missing bridge and conflicts execute original path; captured matcher survives removal of the temporary property',async t=>{for(const options of [{noHelper:true},{conflict:()=>()=>true}]){const f=fixture(t,options);await f.api().warm(metadata(),[]);assert.equal(f.calls.match.length,0);assert.equal(f.calls.digest.length,1);}const f=fixture(t);assert.equal(Object.hasOwn(f.w,'__studySlimLoadCheckerCapture'),false);await f.api().warm(metadata(),[]);assert.equal(f.calls.match.length,1);});
test('both source pins share exact Bank inverse and unknown/drift/duplicate/repeat remain rejected',()=>{
 const edits=vm.runInNewContext(adapterSource.split('  const edits = ')[1].split(';\n  if (edits.some')[0]);assert.equal(hash(baseline),'988fc9f1cc3494669504f50ad621bd707cea14b7242a0788643d711364f711f2');
 for(const pin of [PIN,OTHER]){const result=adapt(baseline,pin);let inverse=result;for(const [before,after]of edits){assert.equal(baseline.split(before).length,2);assert.equal(inverse.split(after).length,2);inverse=inverse.replace(after,before);}assert.equal(inverse,baseline);}
 for(const pin of ['',PIN.toUpperCase(),'f'.repeat(64)])assert.equal(adapt('unrelated',pin),'unrelated');for(const bad of [baseline.replace("'shared bank sidecar byte SHA mismatch'","'changed'"),baseline+baseline,adapt(baseline,PIN)])assert.throws(()=>adapt(bad,PIN),/Audited Bank side checker boundary differs/);
});

test('actual FRAME loop uses the existing one-shot bridge for both Bank SIDE and Slim raw checks',async t=>{
 const f=fixture(t,{deferModule:true,allowAssets:true}),line=process.env.BANK_SIDE_MODULE_LOOP,code=baseline+'\n'+fs.readFileSync(process.env.BANK_SIDE_SLIM_SOURCE,'utf8'),sha=hash(code),events=[],active={modules:new Set()},packet={prepared:{modules:{[PIN]:{src:'evidence/native.js',sha256:sha,original_sha256:PIN}}}};
 const slimAdapt=vm.runInNewContext(read('native-slim-load-checker-adapter.js')+';adaptNativeSlimLoadChecker;'),names=['adaptNativeProjectionLookup','adaptNativeProjectionTask','adaptNativeGroupTranslationText','adaptNativeGroupRanges','adaptNativeGroupCoarseBuckets','adaptSharedReadingBankWarm','adaptNativeFineWholeProbe'];
 const run=new Function('scripts','packet','active','resource','document','valid','execute','doc','win',...names,'withSlimLoadChecker','adaptNativeSlimLoadChecker','adaptNativeBankSideChecker','return(async()=>{'+line+'})();');
 const resource=async(url,pin)=>{assert.equal(Object.hasOwn(f.w,'__studySlimLoadCheckerCapture'),false);assert.equal(url,'https://fixture.test/book/evidence/native.js');assert.equal(hash(code),pin);events.push('resource');return code;};
 const execute=(doc,source,proof)=>{assert.equal(doc,f.doc);assert.equal(proof,PIN+'-prepared-'+sha);assert.equal(typeof f.w.__studySlimLoadCheckerCapture,'function');events.push('execute');f.w.eval(source);};
 const invoke=(valid=()=>true)=>run([{pin:PIN}],packet,active,resource,{baseURI:'https://fixture.test/book/index.html'},valid,execute,f.doc,f.w,...names.map(name=>(raw,pin)=>{assert.equal(pin,PIN);events.push(name);return raw;}),f.bridge,slimAdapt,adapt);
 await invoke();assert.deepEqual(events,['resource',...names,'execute']);assert.equal(Object.hasOwn(f.w,'__studySlimLoadCheckerCapture'),false);await f.api().warm(metadata(),[]);const raw='same bridge raw asset',pin=hash(raw);f.w.AnkiSlimAssets[pin]=raw;assert.equal(await f.w.StudySlimWarm.load({src:'_as_'+pin.slice(0,24)+'.js',sha256:pin}),raw);assert.equal(f.calls.match.length,2);assert.equal(f.calls.match[0].pin,SIDE);assert.equal(f.calls.match[1].pin,pin);assert.equal(f.calls.digest.length,0);await invoke();assert.equal(events.filter(x=>x==='execute').length,1);active.modules.clear();events.length=0;await invoke(()=>false);assert.deepEqual(events,['resource']);assert.equal(Object.hasOwn(f.w,'__studySlimLoadCheckerCapture'),false);
});
